{
    "predictors": [
        {
            "name": "Patent Innovation Intensity",
            "construction": "Number of new patents granted in the past year divided by total assets.",
            "rationale": "Firms with higher patenting activity may indicate innovative capacity, leading to competitive advantages and future growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Insider Buy Ratio",
            "construction": "Ratio of insider shares purchased to insider shares sold over the past six months.",
            "rationale": "Increased insider buying relative to selling may signal management's confidence in the firm's future prospects.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Supply Chain Network Centrality",
            "construction": "Centrality score of a firm within its supply chain network, calculated using network analysis on customer-supplier relationships.",
            "rationale": "Firms central to their industry supply chains may have better information flow and strategic importance, potentially leading to superior performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Satisfaction Index",
            "construction": "Average rating from employee satisfaction surveys over the past year.",
            "rationale": "Higher employee satisfaction can lead to improved productivity and lower turnover, enhancing firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Digital Presence Growth",
            "construction": "Growth rate of online engagement metrics (e.g., website traffic, social media mentions) over the past year.",
            "rationale": "Rapid growth in digital presence may indicate strong brand recognition and potential for increased consumer demand.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Climate Risk Exposure",
            "construction": "Estimated carbon emissions intensity (total emissions divided by revenue) over the past year.",
            "rationale": "Firms with lower exposure to climate risks may avoid regulatory costs and benefit from shifts in consumer preferences.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "CEO Media Sentiment",
            "construction": "Average sentiment score of media articles mentioning the CEO over the past year, calculated using natural language processing.",
            "rationale": "Positive media sentiment towards a CEO can enhance the firm's public image and investor confidence.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Concentration Risk",
            "construction": "Revenue from the top five customers divided by total revenue over the past year.",
            "rationale": "Firms with a diversified customer base may be less vulnerable to demand shocks, leading to more stable and potentially higher returns.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "R&D Expense Volatility",
            "construction": "Standard deviation of quarterly R&D expenses over the past three years scaled by mean R&D expenses.",
            "rationale": "Stable R&D spending can indicate consistent innovation efforts, while volatility may signal strategic uncertainty.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Market Sentiment Divergence",
            "construction": "Difference between analyst consensus rating changes and social media sentiment changes over the past quarter.",
            "rationale": "Divergence can signal market mispricing, with potential for correction as sentiment aligns.",
            "higher_returns_for": "high values of the measure when divergence is positive"
        }
    ]
}
